import dbConnect from '../../../lib/dbConnect';
import Otp from '../../../models/Otp';
import { NextResponse } from 'next/server';

export async function POST(request) {
  await dbConnect();

  try {
    const { mobile, otp } = await request.json();

    if (!mobile || !otp) {
      return NextResponse.json({ success: false, message: 'Mobile number and OTP are required.' }, { status: 400 });
    }

    // Find the most recent OTP for this number
    const foundOtp = await Otp.findOne({ mobile }).sort({ createdAt: -1 });

    if (!foundOtp) {
      return NextResponse.json({ success: false, message: 'Invalid OTP or OTP has expired.' }, { status: 400 });
    }

    if (foundOtp.otp !== otp) {
      return NextResponse.json({ success: false, message: 'Invalid OTP.' }, { status: 400 });
    }

    // OTP is correct, delete it to prevent reuse
    await Otp.deleteOne({ _id: foundOtp._id });

    return NextResponse.json({ 
        success: true, 
        message: 'OTP verified successfully.'
    }, { status: 200 });

  } catch (error) {
    console.error('Verify OTP Error:', error);
    return NextResponse.json({ success: false, message: 'Server error while verifying OTP.' }, { status: 500 });
  }
}

import dbConnect from '../../../lib/dbConnect';
import Code from '../../../models/Code';
import Redemption from '../../../models/Redemption';
import { NextResponse } from 'next/server';
import crypto from 'crypto'; // Import the crypto module

// Function to generate a random amount within a range using crypto.randomInt
function getRandomCashback(min, max) {
    // crypto.randomInt(min, max) generates a random integer between min (inclusive) and max (exclusive).
    // To make max inclusive, we use max + 1.
    return crypto.randomInt(min, max + 1);
}

export async function POST(request) {
  await dbConnect();

  try {
    const { 
      code, 
      buyerName, 
      buyerMobile, 
      paymentMethod, 
      upiId, 
      bankDetails 
    } = await request.json();

    // 1. Find the code
    const foundCode = await Code.findOne({ code });

    if (!foundCode) {
      return NextResponse.json({ success: false, message: 'Invalid code provided for redemption.' }, { status: 400 });
    }

    if (foundCode.status === 'redeemed') {
      return NextResponse.json({ success: false, message: 'This code has already been redeemed.' }, { status: 400 });
    }

    if (foundCode.status === 'expired') {
      return NextResponse.json({ success: false, message: 'This code has expired.' }, { status: 400 });
    }

    // 2. Generate random cashback amount using crypto.randomInt
    const cashbackAmount = getRandomCashback(5, 500);

    // 3. CRITICAL STEP: Mark code as redeemed and store cashback amount
    foundCode.status = 'redeemed';
    foundCode.redeemedAt = new Date();
    foundCode.cashbackAmount = cashbackAmount; // Store the determined amount
    await foundCode.save();

    // 4. Simulate payout and generate a transaction ID
    const payoutTransactionId = `TXN-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
    const payoutStatus = 'initiated'; // In a real system, this would come from the payment gateway

    // 5. Create a new Redemption entry
    const redemption = await Redemption.create({
      codeId: foundCode._id,
      buyerName,
      buyerMobile,
      cashbackAmount, // Store the determined amount
      upiId: paymentMethod === 'upi' ? upiId : undefined,
      bankDetails: paymentMethod === 'bank' ? bankDetails : undefined,
      payoutStatus,
      payoutTransactionId,
      redeemedAt: new Date(),
    });

    // Link the redemption to the code
    foundCode.redeemedBy = redemption._id;
    await foundCode.save();


    return NextResponse.json({ 
        success: true, 
        message: 'Cashback redemption successful and payout initiated.',
        data: {
            cashbackAmount,
            payoutTransactionId,
            redemptionId: redemption._id
        }
    }, { status: 200 });

  } catch (error) {
    console.error('Redeem Payout Error:', error);
    // If something goes wrong after marking the code as redeemed,
    // you might want to implement a rollback or a manual review process.
    return NextResponse.json({ success: false, message: 'Server error during cashback redemption.' }, { status: 500 });
  }
}

import dbConnect from '../../../../lib/dbConnect';
import AdminUser from '../../../../models/AdminUser';
import jwt from 'jsonwebtoken';
import { setCookie } from 'cookies-next';
import { NextResponse } from 'next/server';

export async function POST(request) {
  await dbConnect();

  try {
    const { username, password } = await request.json();

    if (!username || !password) {
      return NextResponse.json({ success: false, message: 'Please provide username and password.' }, { status: 400 });
    }

    const user = await AdminUser.findOne({ username: username.toLowerCase() }).select('+password');

    if (!user) {
      return NextResponse.json({ success: false, message: 'Invalid credentials.' }, { status: 401 });
    }

    const isMatch = await user.matchPassword(password);

    if (!isMatch) {
      return NextResponse.json({ success: false, message: 'Invalid credentials.' }, { status: 401 });
    }

    // If credentials are correct, create a JWT
    const token = jwt.sign(
      { isAdmin: true, username: user.username },
      process.env.JWT_SECRET,
      { expiresIn: '1d' } // Token expires in 1 day
    );

    const response = NextResponse.json({ success: true, message: 'Login successful.' });

    // Set the JWT in a secure, http-only cookie
    setCookie('auth_token', token, {
      req: request,
      res: response,
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      maxAge: 60 * 60 * 24, // 1 day
      path: '/',
    });

    return response;

  } catch (error) {
    console.error('Admin Login Error:', error);
    return NextResponse.json({ success: false, message: 'Server error during admin login.' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';

export function middleware(request) {
  const { pathname } = request.nextUrl;
  const authTokenCookie = request.cookies.get('auth_token');

  // If there's no auth token and the user is trying to access a protected admin page
  if (!authTokenCookie && pathname.startsWith('/admin/') && !pathname.startsWith('/admin/login')) {
    // Redirect to the login page
    return NextResponse.redirect(new URL('/admin/login', request.url));
  }

  // A basic check for API routes as well. The actual validation happens in the route itself.
  if (!authTokenCookie && pathname.startsWith('/api/admin/') && !pathname.startsWith('/api/admin/login')) {
    return new NextResponse(JSON.stringify({ success: false, message: 'Unauthorized: No auth token found.' }), { status: 401, headers: { 'Content-Type': 'application/json' } });
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/admin/:path*', '/api/admin/:path*'],
};

